/*
 * A083855  Multiplicands in the list of numbers which are squares, twice
 *          squares, three times squares, or six times squares (A083854).
 * https://oeis.org/A083855
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = multiplicand k (∈{1,2,3,6}) of the n‑th smallest number
 *            of the form k·m² (m≥1). The sequence is generated by repeatedly
 *            selecting the smallest current value among the four sequences
 *            k·m², outputting k, incrementing the corresponding m, and
 *            discarding the used value. The results are memoise...
 * Range:     u8 n <= 105, u16 n <= 105, u32 n <= 105, u64 n <= 105,
 *            u128 n <= 105, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

/* The four allowed multipliers. */
static const int ks[4] = {1, 2, 3, 6};

/* Item for the current head of each subsequence. */
typedef struct {
    uint32_t val;   /* Current k·m² as 32‑bit integer (safe up to n≈10⁶). */
    int k;          /* The multiplier (1,2,3 or 6). */
    idx_t m;        /* Current m (starting from 1). */
} Item;

/* Memoisation of already computed terms of the sequence. */
static seq_t *cache = NULL;        /* Array of size 'cache_size'. */
static idx_t cache_size = 0;       /* Current allocated size. */
static idx_t computed = 0;         /* Number of terms already computed. */

/* Helper to update an item after m has been incremented. */
static void update_item(Item *p) {
    /* m is already incremented; recompute k·m². */
    uint64_t t = (uint64_t)p->k * (uint64_t)p->m * (uint64_t)p->m;
    p->val = (uint32_t)t;
}

/* Helper to keep the four items sorted by increasing val. */
static void resort(Item items[4]) {
    /* One item has increased; bubble it forward until order is restored. */
    for (int i = 0; i < 3; ++i) {
        if (items[i].val > items[i+1].val) {
            Item tmp = items[i];
            items[i] = items[i+1];
            items[i+1] = tmp;
        } else {
            break; /* Order satisfied. */
        }
    }
}

/* Primary function. */
seq_t a(idx_t n)
{
    if (n < 1) return 0;          /* undefined for n<1, but safe. */

    /* Need to compute terms up to n. */
    if (n > computed) {
        /* Allocate or grow cache if necessary. */
        if (n > cache_size) {
            idx_t new_size = n;
            seq_t *tmp = (seq_t *)realloc(cache, sizeof(seq_t) * new_size);
            if (!tmp) return 0;          /* allocation failure */
            cache = tmp;
            cache_size = new_size;
        }

        /* Initialise the 4 heads if this is the first computation. */
        static int initialised = 0;
        static Item items[4];
        if (!initialised) {
            for (int i = 0; i < 4; ++i) {
                items[i].k = ks[i];
                items[i].m = 1;
                update_item(&items[i]);
            }
            /* Sort once (already sorted but just for safety). */
            for (int i = 0; i < 3; ++i) {
                for (int j = i+1; j < 4; ++j) {
                    if (items[i].val > items[j].val) {
                        Item tmp = items[i];
                        items[i] = items[j];
                        items[j] = tmp;
                    }
                }
            }
            initialised = 1;
        }

        /* Compute terms from computed+1 up to n. */
        for (idx_t i = computed; i < n; ++i) {
            /* smallest value is at items[0]. */
            cache[i] = (seq_t)items[0].k;

            /* advance this subsequence */
            items[0].m += 1;
            update_item(&items[0]);

            /* Restore sorted order of the 4 items. */
            resort(items);
        }

        computed = n;
    }

    return cache[n-1];
}
